### Contributing guidelines

- [X] I have read [CODE_OF_CONDUCT.md](https://github.com/nvim-mini/mini.nvim/blob/main/CODE_OF_CONDUCT.md)

### Module(s)

mini.pick

### Question

I want to make mini.pick open all marked files when I execute choose actions (`choose_marked`, `choose_in_*`). For me, opening files as buffers/splits/tabs is a lot more useful than populating the quickfix list. Any advice? I was trying to use `source.choose_marked` and `mini_pick.default_choose_marked` but I'm not sure how.

My relevant config section:
```lua
mini_pick.setup({
	-- TODO: open multiple
	mappings = {
		-- choose = "<cr>",
		-- choose_marked = "<a-cr>",
		choose_in_split = "<a-j>",
		choose_in_vsplit = "<a-l>",
		choose_in_tabpage = "<a-t>",

		refine = "<a-space>",
		refine_marked = "<c-space>",

		-- TODO: fix focus
		choose_left = {
			char = "<a-h>",
			func = function()
				vim.cmd("leftabove vsplit " .. mini_pick.get_picker_matches().current)
				return true
			end,
		},

		-- TODO: fix focus
		choose_up = {
			char = "<a-k>",
			func = function()
				vim.cmd("leftabove split " .. mini_pick.get_picker_matches().current)
				vim.cmd("wincmd k")
				return true
			end,
		},

		mark_down = {
			char = "<c-t>",
			func = input_actions("mark", "move_down"),
		},

		mark_up = {
			char = "<c-a-t>",
			func = input_actions("mark", "move_up"),
		},
	},

	source = {
		choose_marked = mini_pick.default_choose_marked(mini_pick.get_picker_matches() or {}, { list_type = "location" }),
	},

	window = {
		-- center
		config = function()
			local height = math.floor(0.75 * vim.o.lines)
			local width = math.floor(0.75 * vim.o.columns)
			return {
				anchor = 'NW',
				height = height,
				width = width,
				row = math.floor(0.5 * (vim.o.lines - height)),
				col = math.floor(0.5 * (vim.o.columns - width)),
			}
		end,
	},

})
```

